4	import org.springframework.jdbc.core.JdbcTemplate;
5	
6	/**
7	 * 测试上下文销毁时释放命名 H2 内存库：DB_CLOSE_DELAY=-1 使库不随连接关闭，
8	 * 因此在 JVM 退出前显式 SHUTDOWN，避免库在上下文结束后仍驻留。
9	 */
10	public class H2ShutdownBean implements DisposableBean {
11	
12	    private final JdbcTemplate jdbc;
13	
14	    public H2ShutdownBean(JdbcTemplate jdbc) {
15	        this.jdbc = jdbc;
16	    }
17	
18	    @Override
19	    public void destroy() {
20	        jdbc.execute("SHUTDOWN");
21	    }
22	}
