package com.example.starter.blind.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotNull;

/**
 * 中心激活请求体。
 *
 * @param targetCap 中心目标入组上限（人），正整数；生效时据此减去累计已分配数得到剩余容量
 */
public record CreateCenterRequest(
        @NotNull(message = "targetCap 不能为空")
        @Min(value = 1, message = "中心目标入组上限必须为正整数")
        @Max(value = 100000, message = "中心目标入组上限不能超过 100000")
        Integer targetCap
) {
}

package com.example.starter.blind.dto;

import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

import java.util.List;

/**
 * 创建协议修订请求体（支持单条或批量）。
 * 比例均为正整数且总和 100；生效时刻为 Unix 毫秒 UTC，不得早于当前时刻。
 *
 * @param ratioA      A 组区组比例（百分比），1~99
 * @param ratioB      B 组区组比例（百分比），1~99，与 ratioA 之和为 100
 * @param effectiveAt 生效时刻，Unix 毫秒，UTC
 */
public record CreateAmendmentRequest(
        @NotNull(message = "ratioA 不能为空")
        @Positive(message = "比例必须为正整数")
        Integer ratioA,
        @NotNull(message = "ratioB 不能为空")
        @Positive(message = "比例必须为正整数")
        Integer ratioB,
        @NotNull(message = "effectiveAt 不能为空")
        Long effectiveAt
) {

    /** 批量创建修订；只允许一条最终待生效版本。 */
    public record Batch(@NotNull(message = "amendments 不能为空") List<CreateAmendmentRequest> amendments) {
    }
}

package com.example.starter.blind.dto;

/**
 * 中心序列视图：中心在某协议版本下预留的独立盲码序列容量与消耗进度；不暴露未使用盲码。
 *
 * @param experimentId 实验编号
 * @param centerId     中心编号
 * @param version      协议版本号，该序列永远归属此版本
 * @param total        预留盲码总条数（= 生效时该中心剩余容量）
