    /** 查询某版本某席位的处理代码（盲底，仅供揭盲批准使用）。 */
    public String findTreatment(String experimentId, int version, int blockNo, int seatNo) {
        return jdbc.query(
                "SELECT treatment FROM protocol_seat "
                        + "WHERE experiment_id = ? AND version = ? AND block_no = ? AND seat_no = ?",
