/**
 * 旧的无中心全局登记：在初始协议 V1（seat 表）中按区组、席位顺序领取第一个空位。
 *
 * @return 领取到的席位；实验满额时返回 null
 */
public VacantSeat takeFirstVacantSeat(String experimentId) {
    return takeFirstVacantSeat(experimentId, 1, "seat");
}

/**
 * 在指定协议版本的席位集合中领取第一个空位：V1 使用 seat 表，V2+ 使用 protocol_seat 表；
 * 只与同版本的已有分配比较，因此不同版本的席位互不影响。
 *
 * @return 领取到的席位；该版本满额时返回 null
 */
public VacantSeat takeFirstVersionVacantSeat(String experimentId, int version) {
    String seatTable = version == 1 ? "seat" : "protocol_seat";
    return takeFirstVacantSeat(experimentId, version, seatTable);
}

