    long centerAllocated = allocationRepository.countByExperimentAndVersionAndCenter(
            experimentId, version);
    long free = existingSeats - centerAllocated;
    int nextBlockNo = nextBlockNo(experimentId, version, (int) existingBlocks);
    while (free < neededFree) {
        for (int seatNo = 1; seatNo <= block.seatsPerBlock(); seatNo++) {
            String treatment = seatNo <= block.aPerBlock() ? "A" : "B";
            protocolSeatRepository.insert(experimentId, version, nextBlockNo, seatNo, treatment);
        }
        free += block.seatsPerBlock();
        nextBlockNo++;
    }
}

private int nextBlockNo(String experimentId, int version, int existingBlocks) {
    if (existingBlocks > 0) {
        Integer max = jdbc.queryForObject(
                "SELECT MAX(block_no) FROM protocol_seat "
                        + "WHERE experiment_id = ? AND version = ?",
                Integer.class, experimentId, version);
        return (max == null ? 0 : max) + 1;
    }
    if (version == 1) {
        // 避开实验创建时固定的 V1 区组编号 1..blockCount。
        return experimentRepository.findById(experimentId).blockCount() + 1;
    }
    return 1;
}

