        assertEquals("c1", body.path("revokedBy").asText());

        // 记录保留
        assertEquals("REVOKED", jdbc.queryForObject(
                "SELECT status FROM protocol_version WHERE experiment_id = 'PV-4' AND version = 2",
                String.class));

        // 撤销后释放待生效名额：可再创建一条（版本号 3）
